import unittest

from solucao import trocar


class TestTrocarUmPedaco(unittest.TestCase):
    def test_troca_todas_as_vezes(self):
        """trocar devolve o texto com todas as vezes do pedaco trocadas"""
        self.assertEqual(trocar("banana", "a", "o"), "bonono")

    def test_troca_uma_vez_so(self):
        """trocar devolve o texto com uma unica troca"""
        self.assertEqual(trocar("casa", "s", "z"), "caza")

    def test_sem_match_devolve_igual(self):
        """trocar devolve o texto igual quando o pedaco nao existe"""
        self.assertEqual(trocar("abc", "x", "y"), "abc")

    def test_pedaco_maior_que_uma_letra(self):
        """trocar troca pedacos de mais de uma letra"""
        self.assertEqual(trocar("ola mundo", "mundo", "pessoal"), "ola pessoal")
